package io.knowledgebrain.learning;
import java.io.IOException;import java.util.*;import jakarta.servlet.http.HttpServletRequest;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import io.micrometer.core.instrument.MeterRegistry;
@RestController
@ConditionalOnProperty(name="brain.learning.api.enabled",havingValue="true")
@RequestMapping("/api/spaces/{spaceId}/roadmaps/{roadmapId}/{evidenceType}/{evidenceId}/study-session")
final class EvidenceSessionController {
 private final EvidenceSessionStore store;private final RoadmapController authority;private final MeterRegistry metrics;
 EvidenceSessionController(EvidenceSessionStore store,RoadmapController authority,MeterRegistry metrics){this.store=store;this.authority=authority;this.metrics=metrics;}
 static String kind(String type){return switch(type){case "evidence"->"NOTE";case "concept-evidence"->"CONCEPT";case "media-evidence"->"MEDIA";case "github-evidence"->"GITHUB";default->throw LearningStudyStore.bad();};}
 private UUID auth(UUID space,HttpServletRequest r,boolean write,String trace,String kind){return kind.equals("GITHUB")?authority.authorizeGithub(space,r,write,trace):authority.authorize(space,r,write,trace);}
 private static UUID id(String raw){return RoadmapGraph.id(raw);}
 private void count(String op){metrics.counter("brain.learning.evidence.sessions","operation",op).increment();}
 private static ResponseEntity<EvidenceSessionStore.Link> response(EvidenceSessionStore.Link value){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).eTag(LearningStudyController.tag("es",value.version())).body(value);}
 @GetMapping ResponseEntity<EvidenceSessionStore.Link> get(@PathVariable String spaceId,@PathVariable String roadmapId,@PathVariable String evidenceType,@PathVariable String evidenceId,HttpServletRequest r){RoadmapController.parameters(r,Set.of());String kind=kind(evidenceType);UUID roadmap=id(roadmapId),evidence=id(evidenceId);auth(id(spaceId),r,false,RoadmapController.parent(r),kind);count("read");return response(store.get(id(spaceId),roadmap,evidence,kind));}
 @PutMapping ResponseEntity<EvidenceSessionStore.Link> change(@PathVariable String spaceId,@PathVariable String roadmapId,@PathVariable String evidenceType,@PathVariable String evidenceId,HttpServletRequest r)throws IOException{RoadmapController.parameters(r,Set.of());String kind=kind(evidenceType);UUID roadmap=id(roadmapId),evidence=id(evidenceId);String trace=RoadmapController.parent(r);UUID actor=auth(id(spaceId),r,true,trace,kind);long expected=LearningStudyController.version(r,"es",true);var body=authority.body(r,4096);if(body.size()!=2||!(body.path("sessionId").isNull()||body.path("sessionId").isString())||!(body.path("sessionVersion").isNull()||body.path("sessionVersion").isIntegralNumber()&&body.path("sessionVersion").canConvertToLong()))throw LearningStudyStore.bad();var input=new EvidenceSessionStore.Input(body.path("sessionId").isNull()?null:id(body.path("sessionId").asString()),body.path("sessionVersion").isNull()?null:body.path("sessionVersion").asLong());var value=store.change(id(spaceId),roadmap,evidence,kind,actor,expected,input,trace.substring(3,35));count("write");return response(value);}
 @GetMapping("/revisions") ResponseEntity<List<EvidenceSessionStore.Revision>> history(@PathVariable String spaceId,@PathVariable String roadmapId,@PathVariable String evidenceType,@PathVariable String evidenceId,HttpServletRequest r){RoadmapController.parameters(r,Set.of("before","limit"));String kind=kind(evidenceType);UUID roadmap=id(roadmapId),evidence=id(evidenceId);long before=RoadmapController.number(r.getParameter("before"),Long.MAX_VALUE,Long.MAX_VALUE);int limit=(int)RoadmapController.number(r.getParameter("limit"),5,10);auth(id(spaceId),r,false,RoadmapController.parent(r),kind);count("history");return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(store.history(id(spaceId),roadmap,evidence,kind,before,limit));}
}
